<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { loadAfterSalesRefundSuggestion, submitAfterSalesRefund, type AfterSalesRefundSuggestion } from '../api/after-sales'
const props=defineProps<{afterSalesId:number}>();const emit=defineEmits<{close:[];saved:[];message:[text:string,kind?:'success'|'error']}>()
const suggestion=ref<AfterSalesRefundSuggestion>();const form=reactive({amount:'',adjustmentReason:''});const error=ref('');const saving=ref(false)
onMounted(async()=>{try{suggestion.value=await loadAfterSalesRefundSuggestion(props.afterSalesId);form.amount=String(suggestion.value.suggestedAmount)}catch(cause){error.value=cause instanceof Error?cause.message:'读取退款建议失败'}})
async function save(){const amount=Number(form.amount),suggested=Number(suggestion.value?.suggestedAmount??0);if(!Number.isFinite(amount)||amount<=0){error.value='退款金额必须大于 0';return}if(amount!==suggested&&!form.adjustmentReason.trim()){error.value='退款金额与建议金额不一致时，请填写调整原因';return}saving.value=true;try{await submitAfterSalesRefund(props.afterSalesId,amount,suggested,form.adjustmentReason.trim()||undefined);emit('message','退款申请已提交，等待财务审核');emit('saved')}catch(cause){error.value=cause instanceof Error?cause.message:'退款申请失败'}finally{saving.value=false}}
</script>
<template><div class="dialog-mask"><section class="dialog-card after-sales-action-dialog" role="dialog" aria-modal="true"><header><div><h2>申请售后退款</h2><p>{{ suggestion?.afterSalesNo }}</p></div><button :disabled="saving" @click="emit('close')">关闭</button></header><form @submit.prevent="save"><div class="form-grid"><label><span>建议退款金额</span><input :value="suggestion?.suggestedAmount??0" disabled></label><label><span>实际退款金额</span><input v-model="form.amount" type="number" min="0.01" step="0.01"></label><label><span>调整原因</span><textarea v-model="form.adjustmentReason" placeholder="金额不一致时必填"></textarea></label></div><p v-if="error" class="form-error">{{ error }}</p><footer class="dialog-actions"><button type="button" class="secondary-action" @click="emit('close')">取消</button><button class="primary-action" :disabled="saving">提交审核</button></footer></form></section></div></template>